@@ -0,0 +1,35 @@
+package main
+
+import (
+	"encoding/json"
+	"fmt"
+	"time"
+
+	"github.com/caddyserver/caddy/v2/modules/caddypki"
+)
+
+func main() {
+	// Test default values
+	pki := caddypki.PKI{}
+	
+	// Check that default values are zero
+	fmt.Printf("Default MaintenanceInterval: %v\n", pki.MaintenanceInterval)
+	fmt.Printf("Default RenewalWindowRatio: %v\n", pki.RenewalWindowRatio)
+	
+	// Test with custom values
+	jsonData := `{
+		"maintenance_interval": "30m",
+		"renewal_window_ratio": 0.3
+	}`
+	
+	err := json.Unmarshal([]byte(jsonData), &pki)
+	if err != nil {
+		fmt.Printf("Error unmarshaling JSON: %v\n", err)
+		return
+	}
+	
+	fmt.Printf("Custom MaintenanceInterval: %v (%v)\n", pki.MaintenanceInterval, time.Duration(pki.MaintenanceInterval))
+	fmt.Printf("Custom RenewalWindowRatio: %v\n", pki.RenewalWindowRatio)
+	
+	fmt.Println("Test completed successfully!")
+}

